 anchors.append({'anchor_id':f'E{len(anchors)+1:02}','feature_id':fid,'observed_label':label,'paper_id':r['paper_id'],'version':r['version'],'source_sha256':m['source_sha256'],'split':'discovery','window_id':r['window_id'],'target_paragraph_id':w['target_paragraph_id'],'target_block_id':r['target_block_id'],'source_locations':[{k:e[k] for k in ['source_file','line_start','line_end']} for e in r['evidence']],'observation':r['rationale'],'selected_item':r.get('items'),'audit_status':r['audit_status'],'annotation_method':'host_agent','source_url':f'https://arxiv.org/abs/{r["paper_id"]}v{r["version"]}','interpretation':'Organization observation, not a readability ranking or endorsement of scientific correctness. Full protected source and exact quotes remain in local annotation cache.'})
