profile={'project':'PhysWhen','version':'candidate-v2','corpus_papers':corpus['papers_included'],'discovery_papers':corpus['split_counts']['discovery'],'heldout_papers':corpus['split_counts']['heldout'],'reference_profiles':profiles['discovery'],'profile_source_sha256':digest(Path('data/features/pilot/feature_profiles.json').read_bytes()),'semantic_samples_separate':{'initial':sem['initial_sample'],'additional':{k:sem[k] for k in ['windows','papers','formula_target_windows','prose_target_windows','section_counts','features']},'inventory_only':sem['combined_inventory_only']},'rules':rules,'status':'candidate_operations_not_human_validated','observation_vs_instruction':'Historical observations motivate candidates; routing, redundancy controls, and scientific preservation are explicit project design decisions, not measured readability effects.','heldout_policy':'42 heldout papers are excluded from candidate-rule statistics and new semantic annotation.','effect_evidence':{'v2_human_readability':'not_established','current_group_study':'frozen v1 rules, not this v2','weight_training':'not_run'},'audit':{'windows':20,'feature_judgments':120,'original_matches':107,'original_disagreements':13,'original_agreement':107/120,'interpretation':audit['agreement_interpretation'],'adjudications':6,'human_gold_standard':False},'limitations':['Purposive local windows; overlapping context; do not pool old and new sampling denominators.','S04 compares one selected local item, not exhaustive/global first-use and not a mandatory before-definition rule.','S05 observes stated textual support, not proof of a valid scientific derivation.','Section roles and paragraph lengths affected by TeX parsing/list boundaries and unsectioned sources; raw display environments are not semantic equation counts.','Known inconsistent source formula and acknowledgment context excluded from reusable scientific examples; source remains unchanged.']}
